const RECOVERY_GUIDE = {"source": "ST0x-Technology/st0x.liquidity dashboard/src/lib/transfer.ts RECOVERY_GUIDE, same commit as this file; regenerate from there, do not edit by hand", "modeLabels": {"requires-bot": "REST \u2014 requires the running bot", "live-rpc-only": "live RPC \u2014 ensure the bot is not driving this same on-chain action", "direct-db-live-rpc": "direct DB + live RPC \u2014 stop the bot / ensure it is not driving this id", "direct-db": "direct DB \u2014 stop the bot / ensure it is not driving this id"}, "groups": [{"object": "transfer", "commands": [{"command": "st0x-liquidity-client --env production debug recheck <mint|redemption|usdc> <id>", "description": "Re-poll the provider and complete the transfer if it has settled.", "whenToUse": "A transfer is stuck or failed but the provider may have settled it.", "appliesTo": "Equity mint / redemption (any non-completed state), failed USDC deposit", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug resume", "description": "Re-drive ALL interrupted mints and redemptions (no id; best-effort per transfer, failures reported as counts).", "whenToUse": "Equity transfers were interrupted mid-flight and need re-driving via the bot.", "appliesTo": "All in-flight equity transfers", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug resume-usdc <alpaca-to-base|base-to-alpaca> <id>", "description": "Re-drive a single USDC bridge on the bot's transfer worker.", "whenToUse": "A USDC bridge stopped mid-flight, before or after the burn.", "appliesTo": "USDC bridge (in-flight)", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug fail-equity-transfer <mint|redemption> <id> --reason \"<reason>\"", "description": "Force a stuck transfer into the terminal Failed state.", "whenToUse": "A mint/redemption is permanently stuck and unrecoverable.", "appliesTo": "Equity mint / redemption (non-terminal)", "mode": "requires-bot"}, {"c